import docx
import json
import re
import sys

def process_paragraph(para, data):
    """
    Process a paragraph to handle conditionals and variable replacements.
    Uses the 'replace full text and put in first run' strategy to handle split placeholders.
    """
    full_text = para.text
    if not full_text:
        return

    original_text = full_text

    # 1. Handle Conditional Blocks (RELOCATION)
    # We look for the pattern {{IF_RELOCATION}}...{{END_IF_RELOCATION}}
    # This assumes the markers are within the same paragraph, which we verified.
    if '{{IF_RELOCATION}}' in full_text and '{{END_IF_RELOCATION}}' in full_text:
        is_relocation = data.get('RELOCATION_PACKAGE', 'No').strip().lower() == 'yes'
        pattern = r'\{\{IF_RELOCATION\}\}(.*?)\{\{END_IF_RELOCATION\}\}'

        def replacer(match):
            if is_relocation:
                return match.group(1) # Keep content inside
            else:
                return "" # Remove content

        # re.DOTALL allows matching across newlines if they exist within the text (though para.text usually handles them as one block)
        full_text = re.sub(pattern, replacer, full_text, flags=re.DOTALL)

    # 2. Handle Variable Replacement
    # Identify all patterns like {{VAR_NAME}}
    # We do this iteratively to ensure we catch everything
    placeholders = re.findall(r'\{\{([A-Z_]+)\}\}', full_text)

    # We want unique placeholders to avoid redundant processing, but order doesn't strictly matter
    # standardizing set conversion
    unique_placeholders = set(placeholders)

    for key in unique_placeholders:
        if key in data:
            val = str(data[key])
            # Replace {{KEY}} with value
            full_text = full_text.replace(f'{{{{{key}}}}}', val)

    # 3. Apply changes if any occurred
    if full_text != original_text:
        if len(para.runs) > 0:
            # Set the new text to the first run
            para.runs[0].text = full_text
            # Clear remaining runs to avoid duplication
            for run in para.runs[1:]:
                run.text = ''
        else:
            # Fallback if no runs exist
            para.add_run(full_text)

def main():
    data_path = 'employee_data.json'
    template_path = 'offer_letter_template.docx'
    output_path = 'offer_letter_filled.docx'

    print(f"Reading data from {data_path}...")
    try:
        with open(data_path, 'r') as f:
            data = json.load(f)
    except Exception as e:
        print(f"Error reading data: {e}")
        sys.exit(1)

    print(f"Opening template {template_path}...")
    try:
        doc = docx.Document(template_path)
    except Exception as e:
        print(f"Error opening template: {e}")
        sys.exit(1)

    print("Processing document...")

    # Process Body Paragraphs
    for para in doc.paragraphs:
        process_paragraph(para, data)

    # Process Tables (and nested tables logic if needed, though simpler here)
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    process_paragraph(para, data)

    # Process Sections (Headers/Footers)
    for section in doc.sections:
        if section.header:
            for para in section.header.paragraphs:
                process_paragraph(para, data)
        if section.footer:
            for para in section.footer.paragraphs:
                process_paragraph(para, data)

    print(f"Saving to {output_path}...")
    try:
        doc.save(output_path)
        print("Done.")
    except Exception as e:
        print(f"Error saving file: {e}")
        sys.exit(1)

if __name__ == '__main__':
    main()

